<script lang="ts">
 import {onMount} from 'svelte';import {Editor} from '@tiptap/core';import Collaboration from '@tiptap/extension-collaboration';import {Bold,Italic,Link2,List,ListOrdered,Redo2,Table2,Underline,Undo2} from '@lucide/svelte';import type * as Y from 'yjs';import {textExtensions} from '../text-schema';import {TEXT_FRAGMENT} from '../contracts';import {TextColorControl} from './text-color-control';
 export let doc:Y.Doc;export let editable:boolean;let element:HTMLDivElement;let editor:Editor|null=null;let revision=0;let selected:any={};
 onMount(()=>{editor=new Editor({element,extensions:[...textExtensions(),Collaboration.configure({document:doc,field:TEXT_FRAGMENT})],editable,editorProps:{attributes:{class:'shared-text-content','aria-label':'Dokumenttext'}},onTransaction:()=>revision++,onSelectionUpdate:()=>revision++});return()=>editor?.destroy();});
 $: editor?.setEditable(editable);
 $: {void revision; selected={table:editor?.isActive('table'),bold:editor?.isActive('bold'),italic:editor?.isActive('italic'),underline:editor?.isActive('underline'),bullet:editor?.isActive('bulletList'),ordered:editor?.isActive('orderedList'),link:editor?.isActive('link'),color:editor?.getAttributes('textStyle').color as string|undefined,heading:editor?.isActive('heading',{level:1})?'1':editor?.isActive('heading',{level:2})?'2':editor?.isActive('heading',{level:3})?'3':'0'};}
 function link(){const url=window.prompt('Link-Adresse',editor?.getAttributes('link').href||'https://');if(url===null)return;if(!url.trim())editor?.chain().focus().extendMarkRange('link').unsetLink().run();else if(/^(?:https?:\/\/|mailto:|tel:)/i.test(url.trim()))editor?.chain().focus().extendMarkRange('link').setLink({href:url.trim()}).run();else window.alert('Bitte verwende eine https://-, http://-, mailto:- oder tel:-Adresse.');}
 $: controls=[{title:'Rückgängig',Icon:Undo2,action:()=>editor?.chain().focus().undo().run()},{title:'Wiederholen',Icon:Redo2,action:()=>editor?.chain().focus().redo().run()},{title:'Fett',Icon:Bold,active:selected.bold,action:()=>editor?.chain().focus().toggleBold().run()},{title:'Kursiv',Icon:Italic,active:selected.italic,action:()=>editor?.chain().focus().toggleItalic().run()},{title:'Unterstrichen',Icon:Underline,active:selected.underline,action:()=>editor?.chain().focus().toggleUnderline().run()},{title:'Aufzählung',Icon:List,active:selected.bullet,action:()=>editor?.chain().focus().toggleBulletList().run()},{title:'Nummerierte Liste',Icon:ListOrdered,active:selected.ordered,action:()=>editor?.chain().focus().toggleOrderedList().run()},{title:'Link',Icon:Link2,active:selected.link,action:link},{title:'Tabelle einfügen',Icon:Table2,action:()=>editor?.chain().focus().insertTable({rows:3,cols:3,withHeaderRow:true}).run()}];
</script>
<div class="shared-text-editor"><div class="document-toolbar" role="toolbar" aria-label="Text formatieren"><select aria-label="Textart" value={selected.heading} disabled={!editable||!editor} on:change={event=>{const level=Number(event.currentTarget.value);if(level)editor?.chain().focus().toggleHeading({level:level as 1|2|3}).run();else editor?.chain().focus().setParagraph().run();}}><option value="0">Normaler Text</option><option value="1">Überschrift 1</option><option value="2">Überschrift 2</option><option value="3">Überschrift 3</option></select>{#each controls as {title,Icon,active,action} (title)}<button type="button" class={`document-tool ${active?'active':''}`} {title} aria-label={title} aria-pressed={active} disabled={!editable||!editor} on:click={action}><svelte:component this={Icon} size={18}/></button>{/each}<TextColorControl {editor} {editable} color={selected.color}/>{#if selected.table}<button type="button" class="document-tool text-tool" disabled={!editable} on:click={()=>editor?.chain().focus().addRowAfter().run()}>Zeile +</button><button type="button" class="document-tool text-tool" disabled={!editable} on:click={()=>editor?.chain().focus().addColumnAfter().run()}>Spalte +</button><button type="button" class="document-tool text-tool" disabled={!editable} on:click={()=>editor?.chain().focus().deleteTable().run()}>Tabelle entfernen</button>{/if}</div><div class="document-paper-scroll"><div class="document-paper" bind:this={element}></div></div></div>
